from playwright.sync_api import sync_playwright
U="file:///home/claude/meridian/dist/meridian-app.html"
with sync_playwright() as p:
    b=p.chromium.launch()
    pg=b.new_page(viewport={"width":390,"height":844},device_scale_factor=2,color_scheme="light")
    errs=[];pg.on("pageerror",lambda e:errs.append(str(e)))
    pg.goto(U,wait_until="domcontentloaded");pg.wait_for_timeout(400)
    on=lambda:pg.evaluate("[...document.querySelectorAll('.view.on')].map(v=>v.id).join()")
    ov=lambda l:print(l,"|",on(),"| nav hidden:",pg.evaluate("document.getElementById('nav').hidden"),"| ovx:",pg.evaluate("document.documentElement.scrollWidth - window.innerWidth"))
    pg.click("#v-onboarding [data-i=ol]")
    # article
    pg.click("#v-home .lead h2"); pg.wait_for_timeout(150); ov("home->article"); pg.screenshot(path="p2-article.png")
    pg.click("#v-article .aa"); print("size:",pg.get_attribute("#v-article","data-sz"))
    pg.evaluate("window.scrollTo(0,document.body.scrollHeight/2)"); pg.wait_for_timeout(200); print("progress:",pg.evaluate("document.querySelector('#v-article .prog').style.width"))
    pg.click("#v-article .ab a[data-view=company]"); ov("article->company"); pg.click("#nav [data-go=home]")
    # books
    pg.click("#v-home .it >> nth=2"); pg.wait_for_timeout(150); ov("home->book"); print("book:",pg.inner_text("#v-book h1")); pg.screenshot(path="p2-book.png")
    pg.click("#v-book [data-want]"); print("want:",pg.inner_text("#v-book [data-want]"))
    pg.click("#v-book .ppl .p >> nth=0"); ov("book->profile"); pg.click("#nav [data-go=explore]")
    pg.click("#v-explore .sh >> nth=1"); print("shelf->",pg.inner_text("#v-book h1"))
    pg.click("#nav [data-go=explore]"); pg.fill("#v-explore [data-i=q]","goal"); pg.click("#v-explore [data-i=list] a.r[data-book=goal]"); print("explore->",pg.inner_text("#v-book h1"))
    pg.click("#v-book [data-tab=community]"); ov("book->community")
    # player
    pg.click("#nav [data-go=home]"); pg.click("#v-home .it >> nth=1 >> .vth"); pg.wait_for_timeout(2300); ov("home->player")
    print("track:",pg.inner_text("#v-player h1"),"| time:",pg.inner_text("#v-player .cu"),"| playing icon pause:",pg.evaluate("document.querySelector('#v-player .pl').innerHTML.includes('M6 4h4')"))
    pg.screenshot(path="p2-player.png")
    pg.click("#v-player [data-sk='30']"); print("after +30:",pg.inner_text("#v-player .cu"))
    pg.click("#v-player .chp >> nth=2"); print("chapter jump:",pg.inner_text("#v-player .cu"),"| active:",pg.inner_text("#v-player .chp.on"))
    pg.click("#v-player .sd"); print("speed:",pg.inner_text("#v-player .sd"))
    pg.click("#v-player .pl"); print("paused:",pg.evaluate("document.querySelector('#v-player .pl').innerHTML.includes('M7 4.5')"))
    pg.click("#v-player .back"); ov("player back")
    print("mini visible:",pg.evaluate("!document.getElementById('mini').hidden"),"|",pg.inner_text("#mini b")); pg.screenshot(path="p2-mini.png")
    pg.click("#mini .mt"); ov("mini->player"); pg.click("#v-player .back")
    pg.click("#nav [data-go=community]"); print("mini on community, fab shifted:",pg.evaluate("getComputedStyle(document.querySelector('#v-community .fab')).bottom"))
    # live
    pg.click("#v-community .live .join"); pg.wait_for_timeout(150); ov("community->live"); pg.screenshot(path="p2-live.png")
    print("top q:",pg.inner_text("#v-live .q p >> nth=0")[:40])
    pg.click("#v-live .vt >> nth=2"); print("votes after upvote:",pg.evaluate("[...document.querySelectorAll('#v-live .vt')].map(x=>x.textContent)"))
    pg.fill("#v-live .ask input","How do you hire drivers?"); pg.press("#v-live .ask input","Enter"); print("questions:",pg.evaluate("document.querySelectorAll('#v-live .q').length"))
    pg.click("#v-live .rs"); print("hand:",pg.inner_text("#v-live .rs"))
    pg.click("#v-live .back")
    # groups
    pg.click("#v-community .tab >> nth=2"); pg.wait_for_timeout(100); print("groups rows:",pg.evaluate("document.querySelectorAll('#v-community .gr').length"),"| live hidden:",pg.evaluate("document.querySelector('#v-community .live').hidden"))
    pg.screenshot(path="p2-groups.png")
    pg.click("#v-community .gl [data-jn=fintech]"); print("joined sections:",pg.evaluate("[...document.querySelectorAll('#v-community .gl h3')].map(h=>h.textContent)"),pg.evaluate("document.querySelectorAll('#v-community .gl .gr')[0].dataset.group"))
    pg.click("#v-community .gr[data-group=logistics] b"); pg.wait_for_timeout(150); ov("group"); print("group:",pg.inner_text("#v-group h1")); pg.screenshot(path="p2-group.png")
    pg.click("#v-group .btn"); print("group btn:",pg.inner_text("#v-group .btn")); pg.click("#v-group .back")
    pg.click("#v-community .tab >> nth=1"); print("following visible posts:",pg.evaluate("[...document.querySelectorAll('#v-community .post')].filter(p=>!p.hidden).length"))
    pg.click("#v-community .tab >> nth=0"); print("for you posts:",pg.evaluate("[...document.querySelectorAll('#v-community .post')].filter(p=>!p.hidden).length"))
    # notif live + profile + you
    pg.click("#v-community .bell"); pg.wait_for_timeout(600); pg.click("#v-notifs .nr >> nth=1"); ov("notif->live"); pg.click("#v-live .back")
    pg.click("#nav [data-go=home]"); pg.click("#v-home .ppl .p >> nth=0"); pg.click("#v-profile .tab >> nth=2"); pg.click("#v-profile .bk >> nth=1"); print("profile book:",pg.inner_text("#v-book h1")); pg.click("#v-book .back")
    pg.click("#v-profile .tab >> nth=3"); pg.click("#v-profile .iv >> nth=1"); print("profile ep:",pg.inner_text("#v-player h1")); pg.click("#v-player .back")
    pg.click("#nav [data-go=you]"); pg.click("#v-you a.r >> nth=1"); print("you book:",pg.inner_text("#v-book h1")); pg.click("#v-book .back")
    pg.click("#v-you a.r >> nth=2"); print("you ep:",pg.inner_text("#v-player h1"))
    pg.emulate_media(color_scheme="dark"); pg.wait_for_timeout(150); pg.screenshot(path="p2-player-dark.png")
    print("ERRORS:",errs)
    b.close()
